      pt: ["Comprimento: aprox. 1.300 km.", "Afluente do Congo.", "Nasce perto do lago Alberto.", "Navegável para o transporte.", "Rica biodiversidade.", "Cidades: Bunia e Kisangani."],
      fr: ["Longueur : env. 1 300 km.", "Affluent du Congo.", "Prend sa source près du lac Albert.", "Navigable pour le transport.", "Riche biodiversité.", "Villes : Bunia et Kisangani."],
